// init-001-empty-folder: Init creates the host configuration without scripts, every checklist and every prompt template without needing configuration or Specification documents
func TestInit001EmptyFolder(t *testing.T) {
	s := scenarios.New(t, "init-001-empty-folder")
	s.Given(`the "init-empty" project tree`)
	s.And(`the project tree has no "true-bdd"`)
	s.And(`the project tree has no "templates"`)
	s.When(`the System Architect runs "init"`)
	s.Then(`the command exits with code 0`)
	s.And(`every file matching "tmp/true-bdd.log.json" matches "msg":"Created","path":"true-bdd/true-bdd.yaml"`)
	s.And(`exactly 1 file matching "true-bdd/true-bdd.yaml" is created`)
	s.And(`exactly 5 files matching "true-bdd/checklists/*.yaml" are created`)
	s.And(`exactly 30 files matching "templates/*.tpl" are created`)
	s.And(`every file matching "true-bdd/true-bdd.yaml" does not match (?m)^scripts:`)
	s.And(`no file matching "docs/**" is created`)
	s.Done()
}

// init-002-existing-files: Init preserves and reports existing configuration, checklist and template files even when empty or invalid, while creating missing files
func TestInit002ExistingFiles(t *testing.T) {
	s := scenarios.New(t, "init-002-existing-files")
	s.Given(`the "init-existing" project tree`)
	s.And(`the project tree has no "templates/build-code.fix-applier.prompt.tpl"`)
	s.When(`the System Architect runs "init"`)
	s.Then(`the command exits with code 0`)
	s.And(`every file matching "tmp/true-bdd.log.json" matches "msg":"Left existing","path":"true-bdd/true-bdd.yaml"`)
	s.And(`every file matching "tmp/true-bdd.log.json" matches "msg":"Left existing","path":"true-bdd/checklists/build-code.yaml"`)
	s.And(`every file matching "tmp/true-bdd.log.json" matches "msg":"Left existing","path":"templates/build-code.fix-generator.prompt.tpl"`)
	s.And(`every file matching "tmp/true-bdd.log.json" matches "msg":"Created","path":"templates/build-code.fix-applier.prompt.tpl"`)
	s.And(`the file "true-bdd/true-bdd.yaml" is unchanged`)
	s.And(`the file "true-bdd/checklists/build-code.yaml" is unchanged`)
	s.And(`the file "templates/build-code.fix-generator.prompt.tpl" is unchanged`)
	s.And(`the file "templates/build-code.fix-applier.prompt.tpl" is created`)
	s.Done()
}

// start-001-missing-template: Build code with fix refuses a missing fix template before running any tests or AI turns and names the file and init
func TestStart001MissingTemplate(t *testing.T) {
	s := scenarios.New(t, "start-001-missing-template")
	s.Given(`the "start-missing-template" project tree`)
	s.And(`the project tree has no "templates/build-code.fix-applier.prompt.tpl"`)
	s.When(`the System Architect runs "build code --fix"`)
	s.Then(`the command exits with code 1`)
	s.And(`stdout matches templates/build-code.fix-applier.prompt.tpl`)
	s.And(`stdout matches true-bdd init`)
	s.And(`the engine spawned no test runners`)
	s.And(`the engine dispatched 0 AI turns`)
	s.And(`no file outside "tmp" changed`)
	s.Done()
}

